import { AlertTriangle, CheckCircle2, ClipboardCheck, GitBranch, ShieldCheck, Target, TrendingDown } from 'lucide-react'
import type { SecurityAssuranceModel } from './SecurityAssuranceModel'
import { CisoExecutiveTimeline } from './CisoExecutiveTimeline'

export type ExecutiveSecurityModel = SecurityAssuranceModel & { assuranceConflicts?: number; assuranceConfidence?: number; riskDelta?: number; resolved?: number; regressed?: number }

export function CISOExecutiveView({ model, priorities = [], onReviewRisk, onOpenReports, onOpenConflicts }: { model: ExecutiveSecurityModel; priorities?: Array<{ title: string; severity: string; owner: string; due: string }>; onReviewRisk?: () => void; onOpenReports?: () => void; onOpenConflicts?: () => void }) {
  const confidence = model.assuranceConfidence ?? Math.max(0, Math.min(100, model.validationCoverage))
  const riskDelta = model.riskDelta ?? 0
  const resolved = model.resolved ?? 0
  const regressed = model.regressed ?? 0
  const executiveState = regressed > 0 ? 'Attention required' : riskDelta < 0 ? 'Improving' : 'Awaiting measured outcome'
  return <main className="min-h-full bg-background"><header className="border-b px-6 py-6"><div className="mx-auto flex max-w-[1600px] flex-wrap items-start justify-between gap-4"><div><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Executive security posture</div><h1 className="mt-1 text-3xl font-black tracking-tight">CISO Decision Room</h1><p className="mt-2 max-w-2xl text-sm text-muted-foreground">What changed, why it changed, what risk moved, and which decisions require executive attention.</p></div><div className="flex flex-wrap gap-2"><button type="button" onClick={onReviewRisk} className="rounded-lg border px-3 py-2 text-xs font-semibold hover:bg-muted">Review top risks</button>{onOpenConflicts && <button type="button" onClick={onOpenConflicts} className="inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-semibold hover:bg-muted"><GitBranch className="h-3.5 w-3.5" /> Review conflicts</button>}<button type="button" onClick={onOpenReports} className="rounded-lg bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground">Executive reports</button></div></div></header><div className="mx-auto max-w-[1600px] space-y-5 p-6"><section className="grid gap-3 md:grid-cols-2 xl:grid-cols-6"><Kpi label="Security score" value={model.securityScore} suffix="/100" icon={<ShieldCheck className="h-4 w-4" />} trend={model.scoreDelta} /><Kpi label="Critical findings" value={model.critical} icon={<AlertTriangle className="h-4 w-4" />} /><Kpi label="Remediation rate" value={model.remediationRate} suffix="%" icon={<TrendingDown className="h-4 w-4" />} /><Kpi label="Control coverage" value={model.controlCoverage} suffix="%" icon={<ClipboardCheck className="h-4 w-4" />} /><Kpi label="Validation coverage" value={model.validationCoverage} suffix="%" icon={<Target className="h-4 w-4" />} /><Kpi label="Assurance confidence" value={confidence} suffix="%" icon={<CheckCircle2 className="h-4 w-4" />} extra={model.assuranceConflicts ? `${model.assuranceConflicts} conflicts` : 'No conflicts'} /> </section><CisoExecutiveTimeline securityScore={model.securityScore} scoreDelta={model.scoreDelta} riskExposure={model.riskExposure} remediationRate={model.remediationRate} controlCoverage={model.controlCoverage} validationCoverage={model.validationCoverage} assuranceConfidence={confidence} critical={model.critical} conflicts={model.assuranceConflicts ?? 0} /><section className="grid gap-5 xl:grid-cols-[1fr_360px]"><div className="rounded-2xl border bg-card p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="font-semibold">Executive outcome</div><p className="mt-1 text-xs text-muted-foreground">Measured assurance is promoted into the business-facing narrative.</p></div><span className={`rounded-full border px-3 py-1 text-[10px] font-bold uppercase tracking-wider ${regressed > 0 ? 'border-destructive/30 text-destructive' : riskDelta < 0 ? 'border-emerald-500/30 text-emerald-600' : 'text-muted-foreground'}`}>{executiveState}</span></div><div className="mt-5 grid gap-3 sm:grid-cols-4"><Outcome label="Risk delta" value={riskDelta === 0 ? '—' : `${riskDelta > 0 ? '+' : ''}${riskDelta.toFixed(1)}`} detail="vs baseline" good={riskDelta < 0} /><Outcome label="Resolved" value={String(resolved)} detail="measured outcomes" good={resolved > 0} /><Outcome label="Regressed" value={String(regressed)} detail="needs attention" good={regressed === 0} /><Outcome label="Confidence" value={`${confidence}%`} detail={`${model.assuranceConflicts ?? 0} conflicts`} good={confidence >= 80} /></div><div className="mt-5 rounded-xl border bg-muted/10 p-4"><div className="text-[9px] font-bold uppercase tracking-[0.16em] text-muted-foreground">What changed?</div><p className="mt-2 text-sm leading-6 text-muted-foreground">{regressed > 0 ? `${regressed} regression${regressed === 1 ? '' : 's'} detected. Executive attention is required before claiming posture improvement.` : riskDelta < 0 ? `Measured risk decreased by ${Math.abs(riskDelta).toFixed(1)} points across the current assurance window.` : 'No measured risk reduction is available yet. Continue validation before promoting an improvement claim.'}</p></div></div><aside className="rounded-2xl border bg-card p-5"><div className="font-semibold">Decision queue</div><p className="mt-1 text-xs text-muted-foreground">Actions requiring executive attention.</p><div className="mt-4 space-y-2">{priorities.slice(0, 5).map((item) => <div key={`${item.title}-${item.owner}`} className="rounded-xl border p-3"><div className="flex items-start justify-between gap-3"><div className="text-xs font-semibold">{item.title}</div><span className="rounded-full border px-2 py-0.5 text-[9px] uppercase">{item.severity}</span></div><div className="mt-2 text-[10px] text-muted-foreground">Owner: {item.owner} · Due {item.due}</div></div>)}{!priorities.length && <div className="rounded-xl border border-dashed p-5 text-center text-xs text-muted-foreground">No priority actions provided by the current decision source.</div>}</div></aside></section><section className="grid gap-5 lg:grid-cols-3"><Narrative title="Why did it change?" value={model.assuranceConflicts ? `${model.assuranceConflicts} source conflict${model.assuranceConflicts === 1 ? '' : 's'} affect confidence; review correlation before making a high-impact decision.` : 'Current signals are internally consistent within the available assurance data.'} icon={<GitBranch className="h-4 w-4" />} /><Narrative title="Business impact" value={`Critical exposure: ${model.critical}. Open risk exposure: ${model.riskExposure}. Control coverage: ${model.controlCoverage}%.`} icon={<Target className="h-4 w-4" />} /><Narrative title="Recommended next move" value={regressed > 0 ? 'Investigate regressions and re-validate affected controls.' : riskDelta < 0 ? 'Continue monitoring and preserve the evidence chain supporting the improvement.' : 'Collect fresh evidence and complete re-validation before asserting improvement.'} icon={<ShieldCheck className="h-4 w-4" />} /></section><section className="grid gap-3 sm:grid-cols-3"><Signal title="Assurance" value={confidence >= 80 ? 'Strong' : 'Needs focus'} detail={model.assuranceConflicts ? `${model.assuranceConflicts} source conflicts detected` : 'No source conflicts detected'} icon={<CheckCircle2 className="h-4 w-4" />} /><Signal title="Governance" value={model.controlCoverage >= 80 ? 'Healthy' : 'At risk'} detail="Control coverage" icon={<ClipboardCheck className="h-4 w-4" />} /><Signal title="Remediation" value={model.remediationRate >= 80 ? 'On track' : 'Behind'} detail="Remediation rate" icon={<ShieldCheck className="h-4 w-4" />} /></section></div></main>
}
function Kpi({ label, value, suffix, icon, trend, extra }: { label: string; value: number; suffix?: string; icon: React.ReactNode; trend?: number; extra?: string }) { return <div className="rounded-xl border bg-card p-4"><div className="flex items-center gap-2 text-xs text-muted-foreground">{icon}{label}</div><div className="mt-2 text-2xl font-black">{value}<span className="ml-1 text-xs font-semibold text-muted-foreground">{suffix}</span></div>{trend !== undefined && <div className="mt-1 text-[10px] text-muted-foreground">{trend >= 0 ? '+' : ''}{trend} vs previous</div>}{extra && <div className="mt-1 text-[10px] text-muted-foreground">{extra}</div>}</div> }
function Outcome({ label, value, detail, good }: { label: string; value: string; detail: string; good: boolean }) { return <div className="rounded-xl border bg-background p-3"><div className="text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className={`mt-2 text-xl font-black ${good ? 'text-emerald-600' : 'text-foreground'}`}>{value}</div><div className="mt-1 text-[10px] text-muted-foreground">{detail}</div></div> }
function Narrative({ title, value, icon }: { title: string; value: string; icon: React.ReactNode }) { return <div className="rounded-2xl border bg-card p-5"><div className="flex items-center gap-2 text-xs font-semibold">{icon}{title}</div><p className="mt-3 text-sm leading-6 text-muted-foreground">{value}</p></div> }
function Signal({ title, value, detail, icon }: { title: string; value: string; detail: string; icon: React.ReactNode }) { return <div className="rounded-xl border bg-card p-4"><div className="flex items-center gap-2 text-xs font-semibold">{icon}{title}</div><div className="mt-3 text-lg font-black">{value}</div><div className="mt-1 text-[10px] text-muted-foreground">{detail}</div></div> }
